<?php
use PHPUnit\Framework\TestCase;
final class OperationsCenterApiE2ETest extends TestCase {public function test_unauthorized_request_is_rejected():void{$request=new WP_REST_Request('GET','/zincelestial/v1/operations-center');$response=rest_do_request($request);$this->assertSame(401,$response->get_status());}public function test_authorized_response_is_tenant_scoped():void{$admin=self::factory()->user->create(['role'=>'administrator']);wp_set_current_user($admin);$request=new WP_REST_Request('GET','/zincelestial/v1/operations-center');$request->set_param('limit',10);$response=rest_do_request($request);$this->assertSame(200,$response->get_status());$this->assertArrayHasKey('summary',$response->get_data());}public function test_recovery_requires_nonce_and_capability():void{$request=new WP_REST_Request('POST','/zincelestial/v1/operations-center/recovery');$request->set_body_params(['run_id'=>'r','site_id'=>1,'operation'=>'resume']);$response=rest_do_request($request);$this->assertContains($response->get_status(),[401,403]);}}
